Literal.Value:
'{
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "source",
      "source": "dataset",
      "transform": [
        {
          "type": "formula",
          "as": "isSel",
          "expr": "datum.__selected__ === ''on'' ? 1 : 0"
        },
        {
          "type": "aggregate",
          "groupby": [
            "Brand"
          ],
          "fields": [
            "Total Sales",
            "isSel"
          ],
          "ops": [
            "sum",
            "max"
          ],
          "as": [
            "sales",
            "selected"
          ]
        },
        {
          "type": "collect",
          "sort": {
            "field": "sales",
            "order": "descending"
          }
        },
        {
          "type": "joinaggregate",
          "fields": [
            "sales",
            "sales",
            "selected"
          ],
          "ops": [
            "sum",
            "count",
            "max"
          ],
          "as": [
            "total",
            "n",
            "anySel"
          ]
        },
        {
          "type": "window",
          "sort": {
            "field": "sales",
            "order": "descending"
          },
          "ops": [
            "row_number",
            "sum"
          ],
          "fields": [
            null,
            "sales"
          ],
          "as": [
            "index",
            "cumulative"
          ],
          "frame": [
            null,
            0
          ]
        },
        {
          "type": "formula",
          "as": "pct",
          "expr": "datum.sales / datum.total"
        },
        {
          "type": "formula",
          "as": "cumPct",
          "expr": "datum.cumulative / datum.total"
        },
        {
          "type": "formula",
          "as": "indexNorm",
          "expr": "datum.n > 1 ? (datum.index - 1) / (datum.n - 1) : 0"
        },
        {
          "type": "formula",
          "as": "dim",
          "expr": "datum.anySel === 1 && datum.selected !== 1 ? 0.25 : 1"
        }
      ]
    }
  ],
  "description": "Pareto de ventas por categoría con cross-filter (datos Demo)",
  "width": 760,
  "height": 460,
  "padding": 5,
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "title": {
    "text": "Ventas por categoría (Principio de Pareto)",
    "subtitle": "Clic en una barra para filtrar · clic fuera para limpiar",
    "anchor": "middle",
    "fontSize": 16,
    "subtitleFontSize": 11,
    "subtitleColor": "#8a8a8a",
    "offset": 13
  },
  "signals": [
    {
      "name": "plotLeft",
      "value": 150
    }
  ],
  "scales": [
    {
      "name": "y",
      "type": "band",
      "domain": {
        "data": "source",
        "field": "Brand",
        "sort": {
          "field": "sales",
          "op": "max",
          "order": "descending"
        }
      },
      "range": [
        0,
        {
          "signal": "height"
        }
      ],
      "paddingInner": 0.3,
      "paddingOuter": 0.15
    },
    {
      "name": "xBar",
      "type": "linear",
      "domain": {
        "data": "source",
        "field": "sales"
      },
      "range": [
        {
          "signal": "plotLeft"
        },
        {
          "signal": "width"
        }
      ],
      "nice": true,
      "zero": true
    },
    {
      "name": "xPct",
      "type": "linear",
      "domain": [
        0,
        1
      ],
      "range": [
        {
          "signal": "plotLeft"
        },
        {
          "signal": "width"
        }
      ]
    },
    {
      "name": "barColor",
      "type": "linear",
      "domain": [
        0,
        1
      ],
      "range": [
        "#7c7c7c",
        "#e46a63"
      ]
    }
  ],
  "axes": [
    {
      "orient": "bottom",
      "scale": "xPct",
      "format": "%",
      "tickCount": 5,
      "grid": true,
      "gridColor": "#ececec",
      "domain": false,
      "ticks": false,
      "labelColor": "#8a8a8a",
      "title": "% acumulado del total",
      "titleColor": "#8a8a8a",
      "titleFontSize": 10,
      "titlePadding": 6
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "y": {
            "scale": "y",
            "field": "Brand"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "x": {
            "scale": "xBar",
            "value": 0
          },
          "x2": {
            "scale": "xBar",
            "field": "sales"
          },
          "cornerRadiusTopRight": {
            "value": 2
          },
          "cornerRadiusBottomRight": {
            "value": 2
          },
          "tooltip": {
            "signal": "{''Categoría'': datum.Brand, ''Ventas'': format(datum.sales, '',''), ''% contribución'': format(datum.pct, ''.1%''), ''% acumulado'': format(datum.cumPct, ''.1%'')}"
          }
        },
        "update": {
          "fill": {
            "scale": "barColor",
            "field": "indexNorm"
          },
          "fillOpacity": {
            "field": "dim"
          },
          "cursor": {
            "value": "pointer"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "xBar",
            "field": "sales",
            "offset": 6
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "format(datum.sales, '','')"
          },
          "fill": {
            "value": "#595959"
          },
          "fontSize": {
            "value": 10
          }
        },
        "update": {
          "fillOpacity": {
            "field": "dim"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "value": 8
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "field": "Brand"
          },
          "fill": {
            "value": "#333333"
          },
          "fontSize": {
            "value": 11
          }
        },
        "update": {
          "fillOpacity": {
            "field": "dim"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "signal": "plotLeft - 12"
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5
          },
          "align": {
            "value": "right"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "format(datum.pct, ''.1%'')"
          },
          "fill": {
            "value": "#9a9a9a"
          },
          "fontSize": {
            "value": 10
          }
        },
        "update": {
          "fillOpacity": {
            "field": "dim"
          }
        }
      }
    },
    {
      "type": "line",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "xPct",
            "field": "cumPct"
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5
          },
          "stroke": {
            "value": "#2f7ed8"
          },
          "strokeWidth": {
            "value": 2
          },
          "interpolate": {
            "value": "monotone"
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "xPct",
            "field": "cumPct"
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5
          },
          "size": {
            "value": 45
          },
          "fill": {
            "value": "#ffffff"
          },
          "stroke": {
            "value": "#2f7ed8"
          },
          "strokeWidth": {
            "value": 1.5
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "xPct",
            "field": "cumPct",
            "offset": 7
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5,
            "offset": -9
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "format(datum.cumPct, ''.1%'')"
          },
          "fill": {
            "value": "#ffffff"
          },
          "stroke": {
            "value": "#ffffff"
          },
          "strokeWidth": {
            "value": 3.5
          },
          "fontSize": {
            "value": 10
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "source"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "xPct",
            "field": "cumPct",
            "offset": 7
          },
          "y": {
            "scale": "y",
            "field": "Brand",
            "band": 0.5,
            "offset": -9
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "format(datum.cumPct, ''.1%'')"
          },
          "fill": {
